query:
SELECT ?person ?article ?gender ?birth ?orcid ?openalex WHERE {
  ?person wdt:P106 wd:Q169470 .
  ?person wdt:P31 wd:Q5 ;
          wdt:P569 ?birth .
  FILTER(?birth >= "1920-01-01T00:00:00Z"^^xsd:dateTime &&
         ?birth <  "1981-01-01T00:00:00Z"^^xsd:dateTime)
  ?article schema:about ?person ;
           schema:isPartOf <https://en.wikipedia.org/> .
  OPTIONAL { ?person wdt:P21 ?gender . }
  OPTIONAL { ?person wdt:P496 ?orcid . }
  OPTIONAL { ?person wdt:P10283 ?openalex . }
}
